import re
from taf.ul.kpi_selector.utilities.connections_keywords import get_details_to_login_from_init
from taf.ul.kpi_selector.utilities.kpi_logger import log_input_and_output

from taf.sbts.oam.coam.admin import admin
from taf.ul.objectmodelchecker.datamodel.scf.model import SCFFactory


class MySCFParameter(object):
    def __init__(self, app_version, dist_name, param_abbr, list_param, value):
        self.app_version = self._get_app_version(app_version)
        self.version = app_version
        self.dist_name = dist_name
        self.param_abbr = param_abbr
        self.list_param = list_param
        self.value = value

    def __repr__(self):
        return "dist_name: {0} \n abbr: {1} \n value: {2} \n version: {3}".\
            format(self.dist_name, self.param_abbr, self.value, self.version)

    @staticmethod
    def _get_app_version(app_version):
        for version_index in range(len(app_version)):
            if app_version[version_index] == '5':
                return str(app_version[version_index:])


@log_input_and_output
def get_scf_file(local_dir_path, file_name, admin_api_log_dir='/tmp'):
    """
    Gets scf file from BTS via API

    :param local_dir_path: Path where SCF file will be saved
    :param local_dir_path: Str
    :param file_name: Name of scf, this name have to contain extension ".xml" ex. "scf.xml"
    :param file_name: Str
    :param admin_api_log_dir: Path where logs from Admin API will be saved
    :param admin_api_log_dir: Str
    :return: Scf file
    :rtype file XML
    """
    alias = '_ad_get_scf'
    ad = admin()
    bts_host, username, password, bts_port = get_details_to_login_from_init('http')

    ad.connect_to(
        bts_host=bts_host,
        username=username,
        password=password,
        bts_port=bts_port,
        name=alias,
        admin_api_log_dir=admin_api_log_dir
    )
    try:
        ad.get_current_scf_file(local_dir_path=local_dir_path, file_name=file_name, timeout=30, connection=alias)
    finally:
        ad.teardown(connection=alias)


def load_value_from_scf(path):
    """
    Gets all parameters from scf.

    :param path: Path to SCF.xml
    :type path: str
    :return: Return list of objects
    :rtype list of obj
    """
    scf_params = []
    scf_model = SCFFactory(path).get_scf_model()
    for scf_managed_object in scf_model.managed_objects:
        for param in scf_managed_object.parameters:
            if hasattr(param, 'parameters'):
                for param_l in param.parameters:
                    scf_params.append(MySCFParameter(
                        app_version=scf_managed_object.version,
                        dist_name=scf_managed_object.dist_name,
                        param_abbr=param_l.name,
                        list_param=True,
                        value=param_l.value
                    ))
            else:
                scf_params.append(MySCFParameter(
                    app_version=scf_managed_object.version,
                    dist_name=scf_managed_object.dist_name,
                    param_abbr=param.name,
                    list_param=False,
                    value=param.value
                ))
    return scf_params


@log_input_and_output
def get_radio_protocol_from_scf(scf_path, rmod_id):
    """
    Gets radio protocol type from provided scf.

    :param scf_path: Full path to scf file (with xml extension).
    :type scf_path: str
    :param rmod_id: Rmod id from which user wants to get parameter value.
    :type rmod_id: str
    :return: Radio protocol type: CPRI, eCPRI. Empty string when not detected
    :rtype: str
    """
    bts_id = _get_object_id(scf_path, 'MRBTS')
    radio_protocol_type = _get_radio_protocol_type(scf_path, bts_id, rmod_id)

    if 'TDDCPRI' == radio_protocol_type or 'FDDCPRI' == radio_protocol_type:
        return "CPRI"
    elif 'eCPRI' in radio_protocol_type:
        return "eCPRI"
    else:
        return ""


@log_input_and_output
def _get_radio_protocol_type(scf_path, bts_id, rmod_id):
    """
    Gets radio protocol type from provided scf.

    example:look for manageObjects with pattern: MRBTS-1/EQM-1/HWTOP-1/CABLINK-x
            find appropriate object for related rmod id:<p name="secondEndpointDN">MRBTS-1/EQM-1/APEQM-1/RMOD-1</p>
            read value from:<p name="radioProtocolType">FDDCPRI</p>

    :param scf_path: Full path to scf file (with xml extension).
    :type scf_path: str
    :param bts_id: BTS ID of station from which user wants to get parameter value.
    :type bts_id: str
    :param rmod_id: Rmod id from which user wants to get parameter value.
    :type rmod_id: str
    :return: Radio protocol type. Empty string when not detected
    :rtype: str
    """
    objects = _get_objects_from_scf(scf_path)
    endpoint_related_to_rmod = ''

    for elem in objects:
        if 'MRBTS-{}/EQM-1/HWTOP-1/CABLINK-'.format(bts_id) in elem[0] and \
                'secondEndpointDN' in elem[1] and \
                'MRBTS-{}/EQM-1/APEQM-1/RMOD-{}'.format(bts_id, rmod_id) in elem[1]['secondEndpointDN']:
            endpoint_related_to_rmod = elem[0]

            break

    for elem in objects:
        if endpoint_related_to_rmod in elem[0] and \
                'radioProtocolType' in elem[1] and elem[1]['radioProtocolType']:

            return elem[1]['radioProtocolType']

    return ""


@log_input_and_output
def _get_objects_from_scf(path):
    """
    Gets objects' dist names and values from scf.
    :param path: path to scf
    :type path: str
    :return: list of dist names and values of objects from scf
    :rtype: list(tuple(str, dict))
    """
    return [(element.dist_name, {element.param_abbr: element.value}) for element in load_value_from_scf(path)]


@log_input_and_output
def _get_object_id(scf_path, object_type):
    with open(scf_path, 'r+') as f:
        xml = f.read()
        rule = r"(?<=%s-)([0-9]{1,5})" % object_type
        fdd_cell_id_list = re.findall(rule, xml)
        if len(fdd_cell_id_list) > 0:
            fdd_cell_id_list = str(fdd_cell_id_list[0])
            return fdd_cell_id_list
